style.css:
canvas {
    image-rendering: pixelated !important; 
    image-rendering: crisp-edges !important; 
    filter: contrast(115%) saturate(120%) brightness(105%) !important; 
}

html, body {
    image-rendering: auto !important;
    transform-origin: top left !important;
}

* {
    filter: contrast(115%) saturate(120%) brightness(105%) !important;
}
